using namespace formaccept;
int main(int argc,char **argv) {
 QApplication::setAttribute(Qt::AA_DontUseNativeDialogs);QApplication app(argc,argv);app.setOrganizationName("GMATTests");app.setApplicationName("NasaDefaultBodyOrientation");
 try {
  require(argc==4,"Supply startup, independent default-body matrix and body");const auto matrix=QJsonDocument::fromJson(read(QFileInfo(argv[2]).absoluteFilePath())).object();const QString name=argv[3];QJsonObject selected;for(auto v:matrix["cases"].toArray())if(v.toObject()["body"].toString()==name)selected=v.toObject();require(!selected.isEmpty(),"Unknown default body");const auto rows=selected["rows"].toArray();require(rows.size()==84,"Default-body basis matrix absent");Rig rig(QFileInfo(argv[1]).absoluteFilePath());
  QStringList census;for(const auto &body:Moderator::Instance()->GetSolarSystemInUse()->GetBodiesInUse())census<<QString::fromStdString(body);QStringList expectedCensus;for(auto v:matrix["default_bodies"].toArray())expectedCensus<<v.toString();census.sort();expectedCensus.sort();require(census==expectedCensus,"Default-body census differs from complete requirement family");
  QString source="% Exact historical IAU default-body orientation Ω\nSolarSystem.EphemerisSource = DE405;\nSolarSystem.UseTTForEphemeris = false;\nSolarSystem.EphemerisUpdateInterval = 0;\nCreate CoordinateSystem Inertial Fixed;\nInertial.Origin = "+name+";\nInertial.Axes = MJ2000Eq;\nFixed.Origin = "+name+";\nFixed.Axes = MJ2000Eq;\nCreate Spacecraft Sat;\nSat.CoordinateSystem = Inertial;\nSat.DateFormat = TDBModJulian;\nSat.Epoch = '21545';\nSat.DisplayStateType = Cartesian;\nCreate Variable Keep;\nKeep = 41;\nCreate ReportFile States;\nStates.Filename = '"+rig.report+"';\nStates.WriteHeaders = false;\nStates.FixedWidth = false;\nStates.Delimiter = ',';\nStates.Precision = 17;\n";
  QString mission="BeginMissionSequence;\n";const QStringList fields{"X","Y","Z","VX","VY","VZ"};
  for(auto v:rows){const auto row=v.toObject();mission+="Sat.TDBModJulian = "+number(row["tdb_mjd"].toDouble())+";\n";for(int i=0;i<6;++i)mission+="Sat.Inertial."+fields[i]+" = "+number(row["input_state"].toArray()[i].toDouble())+";\n";mission+="Report States Sat.TDBModJulian Sat.A1ModJulian";for(auto frame:QStringList{"Inertial","Fixed"})for(auto field:fields)mission+=" Sat."+frame+"."+field;mission+=";\n";}mission+="Keep = Keep + 1; % preserve following command\n";source+=mission;rig.source->setPlainText(source);const bool built=rig.window.buildScript();events();rig.save("build-messages.txt",rig.messages->toPlainText().toUtf8());require(built,"Default orientation initial Build failed");rig.save("initial.script",source.toUtf8());
  auto open=[&](const QString &resource){auto found=rig.resources->findItems(resource,Qt::MatchExactly|Qt::MatchRecursive);require(found.size()==1,"Default orientation resource absent");rig.resources->itemDoubleClicked(found.first(),0);events();auto *w=rig.area->activeSubWindow();require(w,"Default orientation editor absent");w->showNormal();w->resize(rig.area->viewport()->size());acceptanceView(*w);return w;};
  auto body=[&]{auto *b=dynamic_cast<CelestialBody *>(Moderator::Instance()->GetConfiguredObject(name.toStdString()));require(b&&!b->IsUserDefined(),"Default native body absent");return b;};
  const QStringList properties{"SpinAxisRAConstant","SpinAxisRARate","SpinAxisDECConstant","SpinAxisDECRate","RotationConstant","RotationRate"};
  auto viewBody=[&]{auto *w=open(name);auto *panel=dynamic_cast<CelestialBodyPanel *>(w->widget());require(panel&&!panel->hasChanges(),"Actual default-body panel absent");panel->findChild<QTabWidget *>("bodyPages")->setCurrentIndex(2);events();auto *model=panel->findChild<QLineEdit *>("body_RotationDataSource");const QString wanted=selected["rotation_source"].toString();require(model&&model->isReadOnly()&&model->text()==wanted&&!panel->findChild<QPushButton *>("bodyChoose_RotationDataSource"),"Default model source display differs");require(QString::fromStdString(body()->GetStringParameter(body()->GetParameterID("RotationDataSource")))==wanted,"Default native source differs");for(int i=0;i<6;++i){auto *edit=panel->findChild<QLineEdit *>("body_"+properties[i]);require(edit&&edit->isReadOnly()&&edit->text().toDouble()==selected["orientation_parameters"].toArray()[i].toDouble(),"Default read-only model constants differ from historical PCK");require(body()->GetRealParameter(body()->GetParameterID(properties[i].toStdString()))==selected["orientation_parameters"].toArray()[i].toDouble(),"Native default model constant differs");}acceptanceView(*w);rig.closePanels();};viewBody();
  auto *owner=open("Fixed");auto *panel=dynamic_cast<ResourceEditor *>(owner->widget());require(panel,"Default coordinate editor absent");std::exception_ptr error;
  QTimer::singleShot(0,panel,[&]{auto *d=panel->findChild<QDialog *>("coordinateAxesDialog");try{require(d,"Actual default BodyFixed chooser absent");auto *choice=d->findChild<QComboBox *>("coordinateAxisType");require(choice&&choice->findText("BodyFixed")>=0,"BodyFixed unavailable");choice->setCurrentText("BodyFixed");events();acceptanceView(*d);d->findChild<QDialogButtonBox *>("resourceButtons")->button(QDialogButtonBox::Apply)->click();require(d->result()==QDialog::Accepted,"Default axes nested Apply failed");}catch(...){error=std::current_exception();if(d)d->reject();}});panel->findChild<QPushButton *>("editCoordinateAxes")->click();if(error)std::rethrow_exception(error);require(panel->hasChanges()&&rig.source->toPlainText()==source,"Nested axes selection bypassed parent Apply");panel->requestApply();events();const auto applied=rig.source->toPlainText();require(applied!=source&&applied.endsWith(mission)&&Moderator::Instance()->GetConfiguredObject("Fixed")->GetStringParameter("Axes")=="BodyFixed","Default frame Apply failed");rig.closePanels();rig.source->undo();require(rig.source->toPlainText()==source&&rig.window.buildScript(),"Default axes Undo failed");rig.source->redo();require(rig.source->toPlainText()==applied&&rig.window.buildScript(),"Default axes Redo failed");
  QJsonArray samples;double maxp=0,maxv=0;for(int phase=0;phase<2;++phase){if(phase){const auto file=rig.files.filePath(name+" IAU Ω.script");require(rig.window.saveScriptTo(file)&&rig.window.loadScript(file)&&rig.window.buildScript()&&rig.source->toPlainText()==applied,"Default Unicode save/reopen failed");viewBody();}rig.messages->clear();const auto result=rig.window.runMission();events();rig.save(QString::number(phase)+"-messages.txt",rig.messages->toPlainText().toUtf8());if(result!=MainWindow::RunResult::Completed)std::cerr<<rig.messages->toPlainText().toStdString();require(result==MainWindow::RunResult::Completed,"Default IAU mission failed");const auto bytes=read(rig.report);rig.save(QString::number(phase)+"-states.csv",bytes);const auto lines=QString::fromUtf8(bytes).trimmed().split('\n');require(lines.size()==rows.size(),"Default IAU raw rows differ");
   for(int row=0;row<rows.size();++row){const auto spec=rows[row].toObject();const auto columns=lines[row].split(',');require(columns.size()==14,"Default IAU report fields differ");QJsonArray raw;for(auto column:columns){bool ok=false;double value=column.toDouble(&ok);require(ok&&std::isfinite(value),"Default IAU report nonfinite");raw.append(value);}require(std::abs(raw[0].toDouble()-spec["tdb_mjd"].toDouble())<=matrix["tdb_tolerance_days"].toDouble(),"Independent TDB epoch differs");for(int i=0;i<6;++i){require(std::abs(raw[2+i].toDouble()-spec["input_state"].toArray()[i].toDouble())<=matrix[i<3?"input_tolerance_km":"velocity_tolerance_km_s"].toDouble(),"Default inertial input differs");const double delta=std::abs(raw[8+i].toDouble()-spec["fixed_state"].toArray()[i].toDouble());if(i<3)maxp=std::max(maxp,delta);else maxv=std::max(maxv,delta);if(delta>matrix[i<3?"position_tolerance_km":"velocity_tolerance_km_s"].toDouble())std::cerr<<"DEFAULT_DIFF body="<<name.toStdString()<<" row="<<row<<" component="<<i<<" error="<<delta<<std::endl;require(delta<=matrix[i<3?"position_tolerance_km":"velocity_tolerance_km_s"].toDouble(),"Default orientation differs from independent historical IAU model");}samples.append(QJsonObject{{"phase",phase},{"row",row},{"raw",raw}});}
   require(Moderator::Instance()->GetInternalObject("Keep")->GetRealParameter("Value")==42&&rig.source->toPlainText()==applied,"Default mission continuation/source changed");auto *output=rig.window.findChild<QTreeWidget *>("Output");auto entries=output->findItems("States",Qt::MatchExactly|Qt::MatchRecursive);require(entries.size()==1,"Default IAU report entry absent");output->itemDoubleClicked(entries.first(),0);events();auto *viewer=rig.area->activeSubWindow();require(viewer&&dynamic_cast<ReportViewer *>(viewer->widget()),"Actual default-body report viewer absent");auto *shown=viewer->findChild<QPlainTextEdit *>();require(shown&&shown->isReadOnly()&&shown->toPlainText().trimmed()==QString::fromUtf8(bytes).trimmed(),"Default report viewer bytes differ");acceptanceView(*viewer);rig.closePanels();
  }
  rig.save("final.script",applied.toUtf8());const QJsonObject proof{{"checkpoint","default-iau-"+name},{"outcome","passed"},{"body",name},{"rotation_source",selected["rotation_source"]},{"orientation_parameters",selected["orientation_parameters"]},{"default_bodies",QJsonArray::fromStringList(census)},{"phases",2},{"samples",samples},{"max_position_error_km",maxp},{"max_velocity_error_km_s",maxv},{"scope","Historical IAU default-body model fidelity with NASA spin-only derivative convention; complete parent needs Earth and Luna proofs and independent audit."}};rig.save("proof.json",QJsonDocument(proof).toJson());std::cout<<"NASA_CHECK "<<QJsonDocument(proof).toJson(QJsonDocument::Compact).constData()<<std::endl;return 0;
 }catch(BaseException&e){std::cerr<<"FAIL "<<e.GetFullMessage()<<std::endl;}catch(std::exception&e){std::cerr<<"FAIL "<<e.what()<<std::endl;}return 1;
}
